package money

import (
	"strconv"
	"strings"
)

// FormatPrice renders cents as a dollar amount, e.g. 1234 -> "$12.34",
// -5 -> "-$0.05".
func FormatPrice(cents int64) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}

	dollars := cents / 100
	remainder := cents % 100

	var b strings.Builder
	if negative {
		b.WriteByte('-')
	}
	b.WriteByte('$')
	b.WriteString(strconv.FormatInt(dollars, 10))
	b.WriteByte('.')
	if remainder < 10 {
		b.WriteByte('0')
	}
	b.WriteString(strconv.FormatInt(remainder, 10))

	return b.String()
}

