package money

import "testing"

func TestFormatPrice(t *testing.T) {
	cases := []struct {
		cents int64
		want  string
	}{
		{0, "$0.00"},
		{5, "$0.05"},
		{-5, "-$0.05"},
		{1234, "$12.34"},
		{-1234, "-$12.34"},
		{100, "$1.00"},
		{99, "$0.99"},
		{100000, "$1000.00"},
	}

	for _, c := range cases {
		if got := FormatPrice(c.cents); got != c.want {
			t.Errorf("FormatPrice(%d) = %q, want %q", c.cents, got, c.want)
		}
	}
}

